import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';

export const PROFILE_ANSWER_KEYS = ['interesting_fact', 'work_reason', 'conservatism_belief'] as const;

export type ProfileAnswerKey = (typeof PROFILE_ANSWER_KEYS)[number];

/** Minimum length for a filled answer. */
export const MIN_ANSWER_LENGTH = 40;

/** Minimum length for the generated bio (only enforced when the bio changes). */
export const MIN_BIO_LENGTH = 200;

/** Flat form values produced by ProfileEditForm. */
export interface ProfileEditValues {
  generated_bio: string;
  profile_picture_url: string;
  interesting_fact: string;
  work_reason: string;
  conservatism_belief: string;
}

const answerField = z.string().trim().max(5000, { message: 'Answer must not exceed 5000 characters' }).default('');

/**
 * Build the profile-edit validation schema. Answers are validated independently:
 *   • A filled answer must be at least MIN_ANSWER_LENGTH characters.
 *   • An answer the backend already has (a key in `requiredAnswerKeys`) cannot be cleared.
 *   • An answer the backend does not have may be left empty (it is only validated if filled).
 * `requiredAnswerKeys` comes from the prefilled answers (see profileAnswersFromDetails),
 * so it must be supplied at runtime rather than baked into a static schema.
 *
 * The MIN_BIO_LENGTH floor is enforced only when the bio actually changes from
 * `initialBio`. A self-editing canvasser cannot hand-edit the bio (they may only
 * regenerate it, which is itself gated on a complete answer set), so a legacy bio
 * shorter than the floor must not block saving an unrelated change such as a new photo.
 */
export function createProfileEditFormSchema(requiredAnswerKeys: ReadonlyArray<ProfileAnswerKey> = [], initialBio = '') {
  const required = new Set(requiredAnswerKeys);
  const normalizedInitialBio = initialBio.trim();
  return toTypedSchema(
    z
      .object({
        profile_picture_url: z
          .string({ message: 'Profile image is required' })
          .min(1, { message: 'Profile image is required' }),
        interesting_fact: answerField,
        work_reason: answerField,
        conservatism_belief: answerField,
        generated_bio: z
          .string({ message: 'Generated bio is required' })
          .trim()
          .min(1, { message: 'Generated bio is required' })
          .max(1000, { message: 'Bio must not exceed 1000 characters' }),
      })
      .superRefine((val, ctx) => {
        // Only hold a changed bio to the minimum length; an unchanged legacy bio passes.
        const bio = val.generated_bio?.trim() ?? '';
        if (bio !== normalizedInitialBio && bio.length < MIN_BIO_LENGTH) {
          ctx.addIssue({
            code: z.ZodIssueCode.custom,
            path: ['generated_bio'],
            message: `Bio must be at least ${MIN_BIO_LENGTH} characters`,
          });
        }
        for (const key of PROFILE_ANSWER_KEYS) {
          const value = val[key] ?? '';
          if (value.length === 0) {
            if (required.has(key)) {
              ctx.addIssue({ code: z.ZodIssueCode.custom, path: [key], message: 'Answer is required' });
            }
            continue;
          }
          if (value.length < MIN_ANSWER_LENGTH) {
            ctx.addIssue({
              code: z.ZodIssueCode.custom,
              path: [key],
              message: `Answer must be at least ${MIN_ANSWER_LENGTH} characters`,
            });
          }
        }
      })
  );
}
