<template>
  <form
    id="profile-edit-form"
    class="self-center flex flex-col gap-6 flex-auto w-full justify-center max-w-[700px] max-lg:px-0"
    @submit="onFormSubmit"
  >
    <Alert v-if="bioErrorMessage" variant="destructive">
      <AlertTitle class="flex gap-2 items-center"><TriangleAlert />Failed to generate bio</AlertTitle>
      <AlertDescription>
        <p class="whitespace-pre-wrap">{{ bioErrorMessage }}</p>
      </AlertDescription>
    </Alert>

    <div class="flex flex-col gap-4">
      <p class="font-medium">Photo</p>
      <FormItemWrapper name="profile_picture_url">
        <template #default="{ slots }">
          <ImageCropUpload
            circle
            helper-text="Click to upload a photo (PNG or JPG)"
            :preview-url="initialData.profile_picture_url ?? undefined"
            :disabled="isSaving || isGeneratingBio"
            v-bind="slots.componentField"
            @update:uploading="(value) => (isPhotoUploading = value)"
          />
        </template>
      </FormItemWrapper>
      <p class="text-sm text-muted-foreground">Photo is required.</p>
    </div>

    <div class="flex flex-col gap-4">
      <p class="font-medium">Questions</p>
      <p class="text-sm text-muted-foreground">All answers must be filled in to regenerate the bio.</p>
      <FormItemWrapper
        v-for="field in answerFields"
        :key="field.id"
        :label="field.question"
        :name="field.id"
        :validate-on-model-update="false"
        :validate-on-blur="false"
        :validate-on-change="false"
      >
        <template #default="{ slots }">
          <Input :id="field.id" type="text" v-bind="slots.componentField" />
        </template>
      </FormItemWrapper>
    </div>

    <div class="flex flex-col gap-4">
      <p class="font-medium">Bio</p>
      <div>
        <Button
          type="button"
          variant="outline"
          :prepend-icon="SparklesIcon"
          :loading="isGeneratingBio"
          :disabled="!allAnswersFilled || isSaving"
          @click="onRegenerateBio"
        >
          Regenerate Bio
        </Button>
      </div>
      <FormItemWrapper
        name="generated_bio"
        :validate-on-model-update="false"
        :validate-on-blur="false"
        :validate-on-change="false"
      >
        <template #default="{ slots }">
          <Textarea
            id="generated_bio"
            rows="10"
            maxlength="1000"
            :disabled="!canEditBioText || isGeneratingBio || isSaving"
            v-bind="slots.componentField"
          />
        </template>
      </FormItemWrapper>
      <p v-if="!canEditBioText" class="text-sm text-muted-foreground">
        Your bio is generated from your answers. Use Regenerate Bio to update it.
      </p>
    </div>

    <Button type="submit" form="profile-edit-form" :loading="isSaving" :disabled="isPhotoUploading || !hasChanges">
      Save
    </Button>

    <NavigationGuard
      v-if="guardUnsavedChanges"
      :saved-data="savedData"
      :changed-data="changedData"
      title="Warning"
      description="You have unsaved changes. Save them before leaving this page."
      confirm-text="Discard Changes"
    />
  </form>
</template>

<script setup lang="ts">
import { useForm } from 'vee-validate';
import { isEqual } from 'lodash';
import { FetchError } from 'ofetch';
import { TriangleAlert, SparklesIcon } from 'lucide-vue-next';
import { useGenerateBio } from '~/mutations/account';
import { QAkeys, type ProfileQAField } from '~/types/account/profileQAFields';
import {
  createProfileEditFormSchema,
  PROFILE_ANSWER_KEYS,
  MIN_ANSWER_LENGTH,
  type ProfileEditValues,
} from '~/constants/validationSchemas/profileEditForm';

export interface ProfileEditInitialData {
  profile_picture_url: string | null;
  bio: string | null;
  answers: ProfileQAField[];
}

interface Props {
  initialData: ProfileEditInitialData;
  canEditBioText: boolean;
  guardUnsavedChanges?: boolean;
  isSaving?: boolean;
  onSubmit: (values: ProfileEditValues, initialPictureUrl: string) => Promise<void>;
}
const props = withDefaults(defineProps<Props>(), {
  guardUnsavedChanges: false,
  isSaving: false,
});

const isPhotoUploading = ref(false);
const answerFields = computed(() => props.initialData.answers);

// Answers the backend already has, indexed by question id. These are required (they can't
// be cleared); a question the backend doesn't know may be left empty. Shared by both the
// validation schema and the unsaved-changes guard so they agree on what "saved" means.
const savedAnswers = computed<Record<string, string>>(() => {
  const result: Record<string, string> = {};
  for (const field of props.initialData.answers) {
    const answer = field.answer?.trim() ?? '';
    if (answer) result[field.id] = answer;
  }
  return result;
});

const requiredAnswerKeys = computed(() => PROFILE_ANSWER_KEYS.filter((key) => key in savedAnswers.value));
const validationSchema = computed(() =>
  createProfileEditFormSchema(requiredAnswerKeys.value, props.initialData.bio ?? '')
);

// `profile_picture_url` from GET is an ephemeral presigned URL, re-issued on every refetch
// (e.g. the post-save `['profile']` invalidation). Snapshot it once at mount — the same value
// the form initialises with below — so a re-issued URL for the *same* image is never mistaken
// for a change. Without this, change-detection re-saves the stale public link and the
// unsaved-changes guard trips spuriously after a background refetch.
//
// It's a ref (not a const) because saving stays on this page: after a successful save we
// advance the baseline to the just-saved value (see onFormSubmit). A fresh upload yields a
// `private_url` that never matches the refetched presigned URL, so a reactive baseline can't
// clear the guard for the photo — we re-baseline imperatively instead.
const initialPictureUrl = ref(props.initialData.profile_picture_url ?? '');

const { handleSubmit, setFieldValue, values } = useForm<ProfileEditValues>({
  validationSchema,
  initialValues: {
    profile_picture_url: initialPictureUrl.value,
    interesting_fact: props.initialData.answers.find((a) => a.id === QAkeys.interesting_fact)?.answer ?? '',
    work_reason: props.initialData.answers.find((a) => a.id === QAkeys.work_reason)?.answer ?? '',
    conservatism_belief: props.initialData.answers.find((a) => a.id === QAkeys.conservatism_belief)?.answer ?? '',
    generated_bio: props.initialData.bio ?? '',
  },
});

// Regenerate needs a complete answer set; gate it on all three being filled.
const allAnswersFilled = computed(() =>
  PROFILE_ANSWER_KEYS.every((key) => ((values[key] as string | undefined)?.trim().length ?? 0) >= MIN_ANSWER_LENGTH)
);

const { generateBio, isGeneratingBio, error: bioError, reset: resetBioError } = useGenerateBio();

// useGenerateBio is a shared defineMutation singleton; clear any error left over from
// another flow (e.g. the create profile page) so it can't render in this freshly-mounted form.
onMounted(() => resetBioError());

// The inline alert is reserved for bio generation failures; form submission
// errors are surfaced as toasts by useEditProfile.
const bioErrorMessage = computed(() => {
  const err = bioError.value;
  if (!err) return null;
  if (err instanceof FetchError && err.data?.detail) return err.data.detail;
  return 'An unexpected error occurred while generating the bio.';
});

async function onRegenerateBio() {
  const answers = props.initialData.answers.map((field) => ({
    question: field.question,
    answer: (values[field.id] as string | undefined) ?? '',
  }));
  try {
    const response = await generateBio({ answers });
    setFieldValue('generated_bio', response.bio);
  } catch (err) {
    console.error('Error regenerating bio:', err);
  }
}

// --- Unsaved-changes guard ------------------------------------------------
// Non-question fields (photo, bio) compare like any other form (mirrors
// SubcontractorCompanyForm). Questions are each tracked independently against
// `savedAnswers` (defined above):
//   • A question the backend already answered always participates in the comparison,
//     prefilled with its saved answer.
//   • A client-only question with no saved backend answer is excluded until the
//     user drafts text into it — an untouched empty answer must not trip the guard.
//   • Backend answers whose question text the client doesn't know never reach this
//     form (profileAnswersFromDetails drops them), so they can't enter the comparison.
const changedAnswers = computed<Record<string, string>>(() => {
  const result: Record<string, string> = {};
  for (const key of PROFILE_ANSWER_KEYS) {
    const current = ((values[key] as string | undefined) ?? '').trim();
    // Compare a question only if the backend already had an answer for it, or the
    // user has now drafted something — client-only questions left empty are skipped.
    if (key in savedAnswers.value || current) result[key] = current;
  }
  return result;
});

const savedData = computed(() => ({
  // Snapshot, not the live prop — the presigned URL churns on refetch (see initialPictureUrl).
  profile_picture_url: initialPictureUrl.value,
  // Trim bio on both sides: the backend stores it trimmed, so after the post-save refetch the
  // saved baseline is trimmed. Comparing it against an untrimmed live value would keep
  // `hasChanges` true and trip the guard over whitespace the server already dropped. (Answers
  // are already trimmed in savedAnswers/changedAnswers.)
  generated_bio: (props.initialData.bio ?? '').trim(),
  answers: savedAnswers.value,
}));

const changedData = computed(() => ({
  profile_picture_url: (values.profile_picture_url as string | undefined) ?? '',
  generated_bio: ((values.generated_bio as string | undefined) ?? '').trim(),
  answers: changedAnswers.value,
}));

// Disable Save until something actually changes — same comparison the guard uses.
const hasChanges = computed(() => !isEqual(savedData.value, changedData.value));

const onFormSubmit = handleSubmit(
  async (formValues) => {
    try {
      await props.onSubmit(formValues, initialPictureUrl.value);
      // Save stays on this page; advance the photo baseline to the just-saved value so the
      // unsaved-changes guard and the Save button settle to "no changes" after a save.
      initialPictureUrl.value = formValues.profile_picture_url;
    } catch {
      // Error toast/alert is surfaced by the mutation; keep form state for retry.
    }
  },
  // Fields are only validated on submit, so an invalid form is otherwise silently blocked.
  // Surface the first validation error as a toast so the user knows why Save didn't proceed.
  ({ errors }) => {
    const firstError = Object.values(errors)[0];
    showToastError(firstError ?? 'Please fix the highlighted fields before saving.', 'Invalid profile');
  }
);
</script>
