import type { BioAnswer, EditProfileRequest } from '~/client';
import type { ProfileQAField } from '~/types/account/profileQAFields';
import type { ProfileEditValues } from '~/constants/validationSchemas/profileEditForm';

// Re-export so existing imports `from '~/utils/buildEditProfileBody'` keep working.
export type { ProfileEditValues };

/**
 * Build the EditProfileRequest body shared by the self and admin edit pages.
 *
 * - profile_picture_url: null means "leave unchanged" (backend copies the object only
 *   when not null), so a new URL is sent ONLY when the photo changed. The prefilled
 *   value is an ephemeral presigned/public URL that must never be re-saved; a fresh
 *   upload yields a private_url.
 * - bio_answers: a question is sent only when it has a non-empty answer OR the backend
 *   already had a saved answer for it. A question the backend doesn't know about and that
 *   is still empty is dropped — it must not create a blank stored answer. Answers are
 *   validated independently, so a partial set is valid (backend-known questions stay
 *   filled — the form enforces it). When nothing qualifies, null is sent so an untouched
 *   form never wipes stored answers.
 */
export function buildEditProfileBody(
  values: ProfileEditValues,
  questions: ProfileQAField[],
  initialPictureUrl: string | null
): EditProfileRequest {
  const answers = questions
    .map((question) => ({
      question: question.question,
      answer: (values[question.id as keyof ProfileEditValues] as string)?.trim() ?? '',
      // The backend already had a saved answer for this question (came back from GET).
      isBackendKnown: Boolean(question.answer?.trim()),
    }))
    .filter((entry) => entry.answer.length > 0 || entry.isBackendKnown)
    .map(({ question, answer }) => ({ question, answer }));
  const bio_answers: BioAnswer[] | null = answers.length > 0 ? answers : null;

  const pictureChanged = values.profile_picture_url !== initialPictureUrl;

  return {
    bio: values.generated_bio,
    bio_answers,
    profile_picture_url: pictureChanged ? values.profile_picture_url : null,
  };
}
