import { buildEditProfileBody, type ProfileEditValues } from '~/utils/buildEditProfileBody';
import { useEditProfile } from '~/mutations/account';
import type { ProfileEditInitialData } from '~/components/account/profile/ProfileEditForm.vue';

/**
 * Shared submit handler for the self and admin profile-edit pages. The body build and the
 * editProfile mutation are identical for both; only `mode` differs. Saving stays on the
 * edit page — the mutation invalidates the profile query, so the form refreshes in place.
 */
export function useProfileEditSubmit(
  mode: 'self' | 'admin',
  userId: MaybeRefOrGetter<string | undefined>,
  initialData: MaybeRefOrGetter<ProfileEditInitialData>
) {
  const { editProfile } = useEditProfile();

  // Drives the Save button's loading state for the duration of the request + refetch.
  const isSaving = ref(false);

  // `initialPictureUrl` is the form's stable snapshot of the prefilled photo URL — NOT
  // re-read from `initialData` here, because that value is an ephemeral presigned URL the
  // profile query re-issues on every refetch. Comparing the live value against the form's
  // snapshot would flag an unchanged photo as changed and re-save the stale public link.
  const onSubmit = async (values: ProfileEditValues, initialPictureUrl: string) => {
    const id = toValue(userId);
    if (!id) return;
    isSaving.value = true;
    try {
      const data = toValue(initialData);
      const body = buildEditProfileBody(values, data.answers, initialPictureUrl);
      await editProfile({ mode, userId: id, body });
    } finally {
      isSaving.value = false;
    }
  };

  return { onSubmit, isSaving };
}
