import { canvasserProfileQuestions } from '~/constants/account';
import type { GetProfileDetailsResponse } from '~/client';
import type { ProfileQAField } from '~/types/account/profileQAFields';

// The backend returns `bio_answers` as a list of { question, answer }. The client owns
// the canonical hardcoded questions (canvasserProfileQuestions). We prefill each
// hardcoded question's answer ONLY when a saved entry's `question` text matches it
// exactly; any hardcoded question without a matching saved answer stays empty (default
// to '' — never fake text, so an untouched save can't overwrite stored answers), and any
// saved answer whose question text is unknown to the client is ignored.
export function profileAnswersFromDetails(details: GetProfileDetailsResponse | null | undefined): ProfileQAField[] {
  const saved = details?.bio_answers ?? [];
  // Index saved answers by question text for an exact-match lookup against our questions.
  const byQuestion = new Map(saved.map((entry) => [entry.question, entry.answer]));
  return canvasserProfileQuestions.map((question) => ({
    ...question,
    answer: byQuestion.get(question.question) ?? '',
  }));
}
