// frontend/mutations/account/editProfile.ts
import { editUserProfile, type EditProfileRequest, type EditProfileResponse } from '~/client';

export interface EditProfileParams {
  mode: 'self' | 'admin';
  userId: string; // own id for self, target id for admin
  body: EditProfileRequest;
}

export const useEditProfile = defineMutation(() => {
  const queryCache = useQueryCache();
  const { userId: myUserId } = useUserRole();
  const { getSession } = useAuth();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (params: EditProfileParams): Promise<EditProfileResponse> =>
      editUserProfile({
        composable: '$fetch',
        path: { user_id: params.userId },
        body: ref(params.body),
      }),
    onSuccess: async (_result, params) => {
      // Refresh the edit form's own data (['profile']) and the admin user-details page
      // (['user']) so both reflect the saved state in place.
      await queryCache.invalidateQueries({ key: ['profile', params.userId] });
      await queryCache.invalidateQueries({ key: ['user', params.userId] });
      // When editing your own profile, also refresh the auth session (sidebar/header
      // avatar + bio) and the account page's profile card (['account']), which is fed by
      // a separate query the lines above don't touch.
      if (params.userId === myUserId.value) {
        await getSession();
        await queryCache.invalidateQueries({ key: ['account'], exact: true });
      }
      showToastSuccess('Profile updated successfully');
    },
    // Form submission errors surface as toasts (not the inline alert, which is
    // reserved for bio generation failures).
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    editProfile: mutateAsync,
    isEditingProfile: computed(() => asyncStatus.value === 'loading'),
  };
});
